"""Evaluation harness: Precision / Recall / FPR per scenario and overall, with ablations and evasive variants.

READ THIS BEFORE QUOTING ANY NUMBER
  * The data is synthetic and generated by ``simulator.py`` - by the same author as the detectors. The detectors'
    thresholds were set while looking at this simulator. Results are a REGRESSION CHECK for the code, not a
    benchmark and not evidence of real-world performance.
  * Unit of evaluation: one AGENT (pseudonym). "Predicted positive" = the agent is in a lead (fused rows) or is
    flagged by that single layer (ablation rows).
  * Per-scenario rows: positives = the agents injected for that scenario; negatives = ALL benign agents. So
    ``FP`` and ``FPR`` are the same benign-population numbers in every row, and ``precision`` for a scenario
    means  TP_scenario / (TP_scenario + all benign false positives).  The overall row pools all scenarios.
  * Hard-negative table: share of each benign group that produced a lead (should be ~0 for crawlers, cron,
    orchestrator pools, broadcasters; non-zero for tool adopters and partner integrations by design - those
    groups are *legitimate behavior changes* that rule R1/R3 cannot distinguish from attacks).
"""
from __future__ import annotations

import hashlib
from dataclasses import dataclass, field
from typing import Any, Dict, Iterable, List, Optional, Set, Tuple

from .baseline import FrozenAnomalyScorer, FrozenBaseline, train_baseline
from .config import Config
from .fusion import fuse
from .layer3_graph import CROSS_IP, REDACTED, SEMANTIC, CoordinationDetector
from .features import group_events
from .normalize import Normalizer
from .pipeline import Pipeline, PipelineResult
from .pseudonymize import Pseudonymizer
from .simulator import EXTENDED_SCENARIOS, SCENARIOS, SimData, build, sim_identity


@dataclass
class Counts:
    tp: int = 0
    fp: int = 0
    fn: int = 0
    tn: int = 0

    def add(self, o: "Counts") -> None:
        self.tp += o.tp; self.fp += o.fp; self.fn += o.fn; self.tn += o.tn

    @property
    def precision(self) -> Optional[float]:
        return self.tp / (self.tp + self.fp) if (self.tp + self.fp) else None

    @property
    def recall(self) -> Optional[float]:
        return self.tp / (self.tp + self.fn) if (self.tp + self.fn) else None

    @property
    def fpr(self) -> Optional[float]:
        return self.fp / (self.fp + self.tn) if (self.fp + self.tn) else None

    def as_dict(self) -> Dict[str, Any]:
        r = lambda v: None if v is None else round(v, 4)
        return {"tp": self.tp, "fp": self.fp, "fn": self.fn, "tn": self.tn,
                "precision": r(self.precision), "recall": r(self.recall), "fpr": r(self.fpr)}


def score_predictions(pred: Set[str], labels: Dict[str, Tuple[str, str]]) -> Dict[str, Counts]:
    """Per-scenario and overall counts. ``pred`` and label keys are raw agent ids."""
    benign = {a for a, (k, _) in labels.items() if k == "benign"}
    fp = len(pred & benign)
    tn = len(benign) - fp
    out: Dict[str, Counts] = {}
    overall = Counts(fp=fp, tn=tn)
    core = Counts(fp=fp, tn=tn)
    present = {g for k, g in labels.values() if k == "positive"}
    for sc in [x for x in SCENARIOS + EXTENDED_SCENARIOS if x in SCENARIOS or x in present]:
        pos = {a for a, (k, g) in labels.items() if k == "positive" and g == sc}
        tp = len(pred & pos)
        out[sc] = Counts(tp, fp, len(pos) - tp, tn)
        overall.tp += tp
        overall.fn += len(pos) - tp
        if sc in SCENARIOS:
            core.tp += tp
            core.fn += len(pos) - tp
    if present - set(SCENARIOS):
        out["overall_core"] = core                    # the original three scenarios only (comparable with v1.0 numbers)
    out["overall"] = overall
    return out


def predictors(res: PipelineResult, data: SimData, cfg: Config, inv: Dict[str, str]) -> Dict[str, Set[str]]:
    """Predicted-positive agent sets (raw ids) for the fused pipeline and each single-layer ablation."""
    back = lambda s: {inv[a] for a in s if a in inv}
    preds: Dict[str, Set[str]] = {"fused_leads": back(res.lead_agents())}
    if res.anomaly is not None:
        preds["isolation_forest_only"] = back(res.anomaly.flagged)
    preds["rules_only"] = back({f.agent for f in res.flags})
    if res.graph is not None:
        preds["graph_only"] = back({m for c in res.graph.active for m in c.members})
        # graph without suppression: re-run the detector with every suppression switched off
        l3 = cfg.layer3.model_copy(update={"suppress_declared_groups": False, "suppress_periodic": False, "suppress_fanout": False})
        by_agent = group_events(res.normalization.events)
        g2 = CoordinationDetector(l3, Pipeline(cfg, data.policy, res.pseudo).resolved).detect(by_agent)
        preds["graph_without_suppression"] = back({m for c in g2.clusters for m in c.members})
    return preds


@dataclass
class RunEval:
    seed: int
    evasive: float
    by_predictor: Dict[str, Dict[str, Counts]]
    hard_negatives: Dict[str, Tuple[int, int]]       # group -> (flagged by fused leads, size)
    n_events: int
    n_leads: int
    guardrail_ok: bool
    checks: Dict[str, Tuple[int, int]] = field(default_factory=dict)


def _eval_key(seed: int) -> bytes:
    """Fixed per-seed key (synthetic data only) so evaluation numbers are reproducible run to run."""
    return hashlib.sha256(f"rogue-eval-synthetic-{seed}".encode()).digest()


@dataclass
class EvalContext:
    """Frozen references shared by every evaluation run: trained ONCE on benign reference data (different seeds from
    the test data), never on the test run itself."""
    baseline: FrozenBaseline                    # trained on ALL benign groups (incl. hard negatives)
    baseline_holdout: FrozenBaseline            # trained with some benign groups REMOVED (unseen-benign stress test)
    holdout_groups: Tuple[str, ...]
    registry: Any
    cfg_identity: Config


HOLDOUT_GROUPS = ("crawler", "compliance_scanner", "cron_declared", "cron_undeclared", "orchestrator_pool", "broadcaster")


def _reference_by_agent(cfg: Config, seeds: Iterable[int], n_assistants: int, drop_groups: Iterable[str] = ()):
    drop = set(drop_groups)
    items: List[Dict[str, Any]] = []
    for k in seeds:
        d = build(k, n_assistants, extended=True, positives=False)
        keep = {a for a, (_, g) in d.labels.items() if g not in drop}
        for e in d.events:
            if e["agent_id"] in keep:
                items.append({**e, "agent_id": f"r{k}-{e['agent_id']}", "event_id": f"r{k}-{e['event_id']}"})
    rep = Normalizer(cfg.normalization, Pseudonymizer(_eval_key(0))).process(items)
    return group_events(rep.events)


def make_context(cfg: Optional[Config] = None, ref_seeds: Iterable[int] = (1000, 1001, 1002), n_assistants: int = 60) -> EvalContext:
    cfg = cfg or Config()
    ref_seeds = list(ref_seeds)
    base = train_baseline(_reference_by_agent(cfg, ref_seeds, n_assistants), cfg, created_at="2026-01-01T00:00:00+00:00")
    hold = train_baseline(_reference_by_agent(cfg, ref_seeds, n_assistants, HOLDOUT_GROUPS), cfg, created_at="2026-01-01T00:00:00+00:00")
    reg, idcfg = sim_identity()
    return EvalContext(base, hold, HOLDOUT_GROUPS, reg, cfg.model_copy(update={"identity": idcfg}))


def _agents(leads) -> Set[str]:
    return {l.agent for l in leads}


def evaluate_once(seed: int, evasive: float = 0.0, cfg: Optional[Config] = None, n_assistants: int = 60,
                  ctx: Optional[EvalContext] = None) -> RunEval:
    """Without ``ctx``: the v1.0 evaluation (batch Isolation Forest, core scenarios). With ``ctx``: the v1.1 evaluation
    (extended scenarios; frozen baseline; sequence model; identity allow-listing) with before/after variants."""
    cfg = cfg or Config()
    if ctx is None:
        data = build(seed, n_assistants, evasive)
        pseudo = Pseudonymizer(_eval_key(seed))
        res = Pipeline(cfg, data.policy, pseudo, run_tag=f"eval-{seed}").run(data.events)
        inv = {pseudo.agent(a): a for a in data.labels}
        preds = predictors(res, data, cfg, inv)
        extra: Dict[str, Any] = {}
    else:
        data = build(seed, n_assistants, evasive, extended=True)
        pseudo = Pseudonymizer(_eval_key(seed))
        res = Pipeline(ctx.cfg_identity, data.policy, pseudo, run_tag=f"eval-{seed}", baseline=ctx.baseline,
                       identity=ctx.registry).run(data.events, alternatives=True)       # identity + frozen + sequence
        inv = {pseudo.agent(a): a for a in data.labels}
        back = lambda s_: {inv[a] for a in s_ if a in inv}
        preds = predictors(res, data, ctx.cfg_identity, inv)
        clusters = res.graph.clusters if res.graph else []
        gate = cfg.sequence.gate
        refuse = lambda anom, seqs, flags=res.flags: back(_agents(fuse(cfg.fusion, anom.agents if anom else {}, flags, clusters, "e", seqs, gate)))
        seqs = res.sequence
        preds["fused_leads"] = back(res.lead_agents())                               # v1.1 default: frozen + sequence + identity
        preds["fused_batch_no_sequence"] = refuse(res.anomaly_batch, {})             # batch Isolation Forest, no sequence gate
        preds["fused_frozen_no_sequence"] = refuse(res.anomaly_frozen, {})           # + frozen baseline
        preds["sequence_only"] = back({a for a, r in seqs.items() if r.score >= gate})
        preds["isolation_forest_batch_only"] = back(res.anomaly_batch.flagged) if res.anomaly_batch else set()
        # same pipeline with identity allow-listing switched off (partner integrations then trip R3)
        res_noid = Pipeline(cfg, data.policy, pseudo, run_tag=f"eval-{seed}", baseline=ctx.baseline).run(data.events)
        preds["fused_no_identity"] = back(res_noid.lead_agents())
        # baseline trained WITHOUT crawlers / scanners / cron / orchestrators / broadcasters: unseen-benign stress test
        by_agent = group_events(res.normalization.events)
        hold_an = FrozenAnomalyScorer(ctx.baseline_holdout, cfg).score(by_agent)
        hold_seq = ctx.baseline_holdout.sequence.score_all(by_agent)
        preds["fused_holdout_baseline"] = refuse(hold_an, hold_seq)
        extra = _extended_checks(res, res_noid, data, inv, pseudo)
    by_pred = {k: score_predictions(v, data.labels) for k, v in preds.items()}
    hn: Dict[str, Tuple[int, int]] = {}
    for a, (kind, grp) in data.labels.items():
        if kind == "benign":
            f, n = hn.get(grp, (0, 0))
            hn[grp] = (f + (a in preds["fused_leads"]), n + 1)
    if ctx is not None:
        for name in ("fused_no_identity", "fused_holdout_baseline", "fused_frozen_no_sequence"):
            for a, (kind, grp) in data.labels.items():
                if kind == "benign":
                    f, n = hn.get(f"{grp}|{name}", (0, 0))
                    hn[f"{grp}|{name}"] = (f + (a in preds[name]), n + 1)
    ok = all(l.severity == "low" and l.automatic_action == "none" and l.recommended_action == "human_review" for l in res.leads)
    return RunEval(seed, evasive, by_pred, hn, len(data.events), len(res.leads), ok, extra)


def _same_cluster(res: PipelineResult, a: str, b: str, kind: Optional[str] = None) -> bool:
    for c in (res.graph.active if res.graph else []):
        if a in c.members and b in c.members:
            return kind is None or any(e.kind == kind and {e.a, e.b} == {a, b} for e in c.edges)
    return False


def _extended_checks(res: PipelineResult, res_noid: PipelineResult, data: SimData, inv_unused, pseudo: Pseudonymizer) -> Dict[str, Tuple[int, int]]:
    """Counters of the form name -> (hits, trials) for the regression-check sections."""
    p = pseudo.agent
    out: Dict[str, Tuple[int, int]] = {}
    ids = set(data.labels)
    # honeypot token passing (deterministic edge): trivially caught by construction
    pass_pairs = [(f"hp-pass-{i}a", f"hp-pass-{i}b") for i in (1, 2, 3)]
    out["hp_handoff pairs joined by a cross_ip_token_handoff edge"] = (sum(_same_cluster(res, p(a), p(b), CROSS_IP) for a, b in pass_pairs), len(pass_pairs))
    sep_pairs = [(f"hp-sep-{i}a", f"hp-sep-{i}b") for i in (1, 2, 3)]
    out["hp_nolink pairs (B did NOT reuse A's token) wrongly joined"] = (sum(_same_cluster(res, p(a), p(b)) for a, b in sep_pairs), len(sep_pairs))
    lead_agents = res.lead_agents()
    out["hp_single agents that produced a lead (R6/R7)"] = (sum(p(f"hp-single-{i}") in lead_agents for i in (1, 2)), 2)
    benign = [a for a, (k, _) in data.labels.items() if k == "benign"]
    hp_flagged = {f.agent for f in res.flags if f.rule_id in ("R6", "R7")}
    out["benign agents (ignoring the honeypot protocol) with an R6/R7 flag"] = (sum(p(a) in hp_flagged for a in benign), len(benign))
    # proxy rotation: sessions of one operator on different IPs stitched together by shared-state edges
    rot = [[f"rot{r}-s{j}" for j in range(1, 6)] for r in (1, 2)]
    joined = 0
    for grp in rot:
        for a, b in zip(grp[:-1], grp[1:]):
            joined += _same_cluster(res, p(a), p(b), SEMANTIC)
    out["proxy_rotation consecutive session pairs stitched by a shared-state edge"] = (joined, 8)
    wrong = 0
    pagers = [f"pager-{i}" for i in range(1, 5)]
    for i, a in enumerate(pagers):
        for b in pagers[i + 1:]:
            wrong += _same_cluster(res, p(a), p(b))
    out["benign pagination clients (own cursor tokens) wrongly joined"] = (wrong, 6)
    # redacted-token markers
    reuse = [(f"reuse{r}-a", f"reuse{r}-b") for r in (1, 2)]
    out["redacted_reuse pairs joined by a moderate shared_redacted_token edge"] = (sum(_same_cluster(res, p(a), p(b), REDACTED) for a, b in reuse), 2)
    reds = [f"redact-{i}" for i in range(1, 9)]
    wr = sum(_same_cluster(res, p(a), p(b), REDACTED) for i, a in enumerate(reds) for b in reds[i + 1:])
    out["benign agents sharing only a POPULAR redacted marker wrongly joined"] = (wr, 28)
    # identity
    pv = [f"pv-{i}" for i in (1, 2, 3)] + [f"pip-{i}" for i in (1, 2)]
    r3 = lambda r: {f.agent for f in r.flags if f.rule_id in ("R3", "R4")}
    out["verified/allow-listed partner agents with R3/R4 flag: identity ON"] = (sum(p(a) in r3(res) for a in pv), len(pv))
    out["verified/allow-listed partner agents with R3/R4 flag: identity OFF"] = (sum(p(a) in r3(res_noid) for a in pv), len(pv))
    sp = [f"spoof-{i}" for i in (1, 2, 3)]
    out["spoofed-identity agents with R3/R4 flag: identity ON (should stay scored)"] = (sum(p(a) in r3(res) for a in sp), 3)
    return out


def aggregate(runs: List[RunEval]) -> Dict[str, Any]:
    """Pool counts over seeds; report min/max across seeds for the fused overall recall and FPR."""
    out: Dict[str, Any] = {"seeds": [r.seed for r in runs], "evasive": runs[0].evasive, "events_per_run": runs[0].n_events,
                           "guardrail_ok": all(r.guardrail_ok for r in runs), "predictors": {}, "hard_negatives": {}}
    names = sorted({k for r in runs for k in r.by_predictor})
    for name in names:
        rows: Dict[str, Counts] = {}
        for r in runs:
            for scn, c in r.by_predictor.get(name, {}).items():
                rows.setdefault(scn, Counts()).add(c)
        out["predictors"][name] = {k: v.as_dict() for k, v in rows.items()}
    rec = [r.by_predictor["fused_leads"]["overall"].recall or 0.0 for r in runs]
    fpr = [r.by_predictor["fused_leads"]["overall"].fpr or 0.0 for r in runs]
    out["fused_overall_recall_range"] = [round(min(rec), 3), round(max(rec), 3)]
    out["fused_overall_fpr_range"] = [round(min(fpr), 3), round(max(fpr), 3)]
    hn: Dict[str, List[int]] = {}
    for r in runs:
        for g, (f, n) in r.hard_negatives.items():
            cur = hn.setdefault(g, [0, 0])
            cur[0] += f
            cur[1] += n
    out["hard_negatives"] = {g: {"flagged": f, "total": n, "rate": round(f / n, 3)} for g, (f, n) in sorted(hn.items())}
    chk: Dict[str, List[int]] = {}
    for r in runs:
        for k, (h, t) in r.checks.items():
            cur = chk.setdefault(k, [0, 0]); cur[0] += h; cur[1] += t
    out["checks"] = {k: {"hits": h, "trials": t} for k, (h, t) in chk.items()}
    return out


def run_evaluation(seeds: Iterable[int] = (0, 1, 2, 3, 4), levels: Iterable[float] = (0.0, 0.5, 1.0),
                   cfg: Optional[Config] = None, extended: bool = True) -> Dict[str, Any]:
    """``extended=True`` (default) is the v1.1 evaluation; ``False`` reproduces the v1.0 harness."""
    cfg = cfg or Config()
    seeds = list(seeds)
    ctx = make_context(cfg) if extended else None
    result: Dict[str, Any] = {"disclaimer": "SYNTHETIC DATA. Regression check, not a benchmark.", "extended": extended, "levels": {}}
    for lv in levels:
        runs = [evaluate_once(s, lv, cfg, ctx=ctx) for s in seeds]
        result["levels"][str(lv)] = aggregate(runs)
    return result


def _p(v: Optional[float]) -> str:
    return "n/a" if v is None else f"{v:.2f}"


_VARIANTS = (("fused_batch_no_sequence", "A. batch IF, no sequence (v1.0-style fusion)"),
             ("fused_frozen_no_sequence", "B. frozen baseline IF, no sequence"),
             ("fused_leads", "C. frozen baseline + sequence gate (v1.1 default)"),
             ("fused_no_identity", "D. = C with identity/allow-listing OFF"),
             ("fused_holdout_baseline", "E. = C but baseline trained WITHOUT crawlers/scanners/cron/orchestrators/broadcasters"))


def format_markdown(result: Dict[str, Any]) -> str:
    lines = ["# Evaluation (SYNTHETIC data - a regression check, not a benchmark)", "",
             "Same author wrote the simulator and the detectors; thresholds were set while looking at this simulator. "
             "Nothing here is evidence about real-world performance. 'Recall' for the honeypot/state-edge scenarios is a "
             "regression check on deterministic logic.", ""]
    names = {"0.0": "standard injected scenarios", "0.5": "mixed: half of injected scenarios use evasive forms",
             "1.0": "evasive: all injected scenarios use evasive forms (timing-throttled, jittered, baseline-seeded)"}
    for lv, agg in result["levels"].items():
        lines += [f"## Evasiveness {lv}: {names.get(lv, '')}", f"Seeds {agg['seeds']}, ~{agg['events_per_run']} events per run. "
                  f"Fused overall recall range across seeds {agg['fused_overall_recall_range']}, "
                  f"FPR range {agg['fused_overall_fpr_range']}.", "",
                  "### Fused pipeline (leads), pooled over seeds", "", "| scenario | TP | FP | FN | TN | precision | recall | FPR |", "|---|---|---|---|---|---|---|---|"]
        for scn, c in agg["predictors"]["fused_leads"].items():
            lines.append(f"| {scn} | {c['tp']} | {c['fp']} | {c['fn']} | {c['tn']} | {_p(c['precision'])} | {_p(c['recall'])} | {_p(c['fpr'])} |")
        P = agg["predictors"]
        if "fused_frozen_no_sequence" in P:
            scn_all = [k for k in P["fused_leads"] if k not in ("overall", "overall_core")]
            lines += ["", "### Before / after (recall per scenario; FPR over ALL benign agents)", "",
                      "| variant | " + " | ".join(scn_all) + " | overall_core recall | overall recall | FPR |",
                      "|---|" + "---|" * (len(scn_all) + 3)]
            for key, label in _VARIANTS:
                row = P[key]
                lines.append(f"| {label} | " + " | ".join(_p(row[s_]["recall"]) for s_ in scn_all) +
                             f" | {_p(row['overall_core']['recall'])} | {_p(row['overall']['recall'])} | {_p(row['overall']['fpr'])} |")
        lines += ["", "### Ablation (overall, agent-level)", "", "| predictor | precision | recall | FPR |", "|---|---|---|---|"]
        for name, rows in P.items():
            c = rows["overall"]
            lines.append(f"| {name} | {_p(c['precision'])} | {_p(c['recall'])} | {_p(c['fpr'])} |")
        hn = agg["hard_negatives"]
        groups = sorted({g.split("|")[0] for g in hn})
        lines += ["", "### Hard negatives: benign groups that produced a lead (leads / agents)", ""]
        if any("|" in g for g in hn):
            vs = [("", "C default"), ("fused_frozen_no_sequence", "B no sequence"), ("fused_no_identity", "D no identity"),
                  ("fused_holdout_baseline", "E held-out baseline")]
            lines += ["| benign group | " + " | ".join(v for _, v in vs) + " |", "|---|" + "---|" * len(vs)]
            for g in groups:
                cells = []
                for key, _ in vs:
                    h = hn.get(g if not key else f"{g}|{key}")
                    cells.append(f"{h['flagged']} / {h['total']}" if h else "-")
                lines.append(f"| {g} | " + " | ".join(cells) + " |")
        else:
            lines += ["| benign group | leads / agents |", "|---|---|"]
            for g, h in hn.items():
                lines.append(f"| {g} | {h['flagged']} / {h['total']} |")
        if agg.get("checks"):
            lines += ["", "### Regression checks (hits / trials, pooled over seeds)", "", "| check | hits / trials |", "|---|---|"]
            for k, h in agg["checks"].items():
                lines.append(f"| {k} | {h['hits']} / {h['trials']} |")
        lines.append("")
    return "\n".join(lines)
